<script lang="ts">
  let distance = $state(10), minutes = $state(50), seconds = $state(0), raceDistance = $state(10), raceMinutes = $state(50);
  const pace = $derived((minutes * 60 + seconds) / distance);
  const fmt = (value: number) => `${Math.floor(value / 60)}:${String(Math.round(value % 60)).padStart(2, '0')}`;
  const prediction = $derived(raceMinutes * Math.pow(21.0975 / raceDistance, 1.06));
  let bodyWeight = $state(70), hours = $state(2);
</script>
<svelte:head><title>Run Tools / Mathieu Coaching</title></svelte:head>
<section class="intro"><span class="eyebrow">No-nonsense run tools / 04</span><h1>USEFUL<br /><em>NUMBERS.</em></h1><p>Small tools for planning an effort. They are guides, not instructions — context still matters.</p></section>
<main>{#snippet field(label: string, value: number, setter: (v: number) => void, unit: string)}<label>{label}<span><input type="number" value={value} oninput={(e) => setter(Number(e.currentTarget.value))} min="0" />{unit}</span></label>{/snippet}
  <section class="tool featured"><div><span class="eyebrow">01 / Pace calculator</span><h2>WHAT DOES<br />THE CLOCK SAY?</h2><p>Enter a completed distance and time to find your average pace.</p></div><div class="inputs">{@render field('Distance', distance, (v) => distance = v, 'km')}{@render field('Minutes', minutes, (v) => minutes = v, 'min')}{@render field('Seconds', seconds, (v) => seconds = v, 'sec')}<output><small>Average pace</small><b>{distance > 0 ? fmt(pace) : '—'} <i>/km</i></b></output></div></section>
  <section class="tool"><div><span class="eyebrow">02 / Race predictor</span><h2>LOOKING<br />AHEAD.</h2><p>Riegel’s formula turns one race effort into an estimated half-marathon time. Treat it as a question, not a promise.</p></div><div class="inputs">{@render field('Recent race distance', raceDistance, (v) => raceDistance = v, 'km')}{@render field('Race time', raceMinutes, (v) => raceMinutes = v, 'min')}<output><small>Half marathon estimate</small><b>{raceDistance > 0 ? fmt(prediction) : '—'} <i>hrs</i></b></output></div></section>
  <section class="tool"><div><span class="eyebrow">03 / Fuel guide</span><h2>FUEL THE<br />SESSION.</h2><p>A broad starting point for long runs and races. Practise your nutrition in training and personalise it where needed.</p></div><div class="inputs">{@render field('Body weight', bodyWeight, (v) => bodyWeight = v, 'kg')}{@render field('Session duration', hours, (v) => hours = v, 'hrs')}<output><small>Suggested carbs per hour</small><b>{hours < 1.25 ? '30' : hours < 2.5 ? '60' : '75'} <i>g/hr</i></b><small class="hint">Approx. {Math.round((hours < 1.25 ? 30 : hours < 2.5 ? 60 : 75) * hours)}g across the session</small></output></div></section>
</main>
